export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  variant?: string;
}

export interface CustomerDetails {
  name: string;
  phone: string;
  address: string;
  landmark?: string;
  notes?: string;
  paymentMethod: 'UPI' | 'Cash on Delivery';
}

export function generateWhatsAppOrderUrl(
  restaurantPhone: string,
  items: CartItem[],
  customer: CustomerDetails,
  deliveryFee: number = 0
): string {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const total = subtotal + deliveryFee;
  const orderDate = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const itemLines = items
    .map(
      (item) =>
        `• ${item.quantity}x ${item.name}${item.variant ? ` (${item.variant})` : ''} - ₹${item.price * item.quantity}`
    )
    .join('\n');

  const messageLines = [
    `*NEW ORDER RECEIVED (${orderDate})*`,
    '------------------------------',
    '*Items:*',
    itemLines,
    '------------------------------',
    `*Subtotal:* ₹${subtotal}`,
    deliveryFee > 0 ? `*Delivery Fee:* ₹${deliveryFee}` : '*Delivery:* Free',
    `*Total Bill:* ₹${total}`,
    '------------------------------',
    '*Customer Details:*',
    `*Name:* ${customer.name}`,
    `*Phone:* ${customer.phone}`,
    `*Address:* ${customer.address}`,
    customer.landmark ? `*Landmark:* ${customer.landmark}` : null,
    `*Payment Mode:* ${customer.paymentMethod}`,
    customer.notes ? `*Notes:* ${customer.notes}` : null,
    '------------------------------',
    'Please reply with *Confirm* to start preparing this order.'
  ].filter(Boolean);

  const encodedMessage = encodeURIComponent(messageLines.join('\n'));
  const cleanPhone = restaurantPhone.replace(/[^0-9]/g, '');

  return `https://wa.me/${cleanPhone}?text=${encodedMessage}`;
}
